import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { useProjectStore } from '../stores/projectStore';
import { useRiskMatrixStore } from '../stores/riskMatrixStore';
import ICAORiskMatrix from './ICAORiskMatrix';
import IntegratedRiskMatrix from './IntegratedRiskMatrix';
import RiskMatrixSelector from './RiskMatrixSelector';

const MatrixDisplay = ({ type }) => {
  switch (type?.toLowerCase()) {
    case 'icao':
      return <ICAORiskMatrix />;
    case 'integrated':
      return <IntegratedRiskMatrix />;
    default:
      return (
        <div className="text-center p-4">
          <p>Please select a risk matrix type to continue</p>
        </div>
      );
  }
};

export default function RiskAssessment() {
  const {
    currentProject,
    hazardIdentificationData,
    setStepData,
    error: storeError,
  } = useProjectStore();
  const { matrixType, setMatrixType } = useRiskMatrixStore();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [localError, setLocalError] = useState(null);
  const events = hazardIdentificationData?.events || [];

  // Initialize form with hazard identification data
  const defaultValues = {
    assessments: events.flatMap(event =>
      (event.hazards || []).flatMap(hazard =>
        (hazard.consequences || []).map(consequence => ({
          consequence_id: consequence.id,
          event: event.name,
          hazard: hazard.description,
          consequence: consequence.description,
          current_controls: consequence.current_controls || '',
          probability: '',
          severity: '',
          likelihood: '',
          impact: '',
          tolerability: ''
        }))
      )
    )
  };

  const { register, handleSubmit, watch } = useForm({ defaultValues });
  const watchAssessments = watch('assessments');

  // Auto-save changes
  useEffect(() => {
    const saveData = async () => {
      try {
        if (!watchAssessments?.length) return;

        // Filter assessments based on matrix type and required fields
        const validAssessments = watchAssessments.filter(assessment => {
          if (!assessment.consequence_id) return false;

          if (matrixType === 'ICAO') {
            return assessment.probability && assessment.severity;
          }
          return assessment.likelihood && assessment.impact;
        });

        if (validAssessments.length > 0) {
          await setStepData(3, { assessments: validAssessments });
        }
      } catch (error) {
        console.error('Error auto-saving:', error);
      }
    };

    const timeoutId = setTimeout(saveData, 1000);
    return () => clearTimeout(timeoutId);
  }, [watchAssessments, setStepData, matrixType]);

  const handleFormSubmit = async data => {
    try {
      setIsSubmitting(true);
      setLocalError(null);

      const { assessments } = data;
      const invalidAssessments = assessments.filter(assessment => !assessment.consequence_id);

      if (invalidAssessments.length > 0) {
        console.error('Invalid assessments detected:', invalidAssessments);
        setLocalError('One or more assessments are missing required fields.');
        return;
      }

      // Format data for submission
      const formattedData = {
        assessments: assessments.map(assessment => ({
          consequence_id: assessment.consequence_id,
          probability: assessment.probability ? parseInt(assessment.probability, 10) : null,
          severity: assessment.severity || null,
          likelihood: assessment.likelihood ? parseInt(assessment.likelihood, 10) : null,
          impact: assessment.impact ? parseInt(assessment.impact, 10) : null,
          tolerability: assessment.tolerability || null
        }))
      };

      await setStepData(3, formattedData);
      setIsSubmitting(false);
    } catch (error) {
      console.error('Error submitting form:', error);
      setLocalError(`Failed to save assessments: ${error.message}`);
      setIsSubmitting(false);
    }
  };

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="mb-8">
        <RiskMatrixSelector />
        <MatrixDisplay type={matrixType} />
      </div>

      {(localError || storeError) && (
        <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
          {localError || storeError}
        </div>
      )}

      <form onSubmit={handleSubmit(handleFormSubmit)}>
        <div className="space-y-6">
          {watchAssessments?.map((assessment, index) => (
            <div key={index} className="bg-white shadow rounded-lg p-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700">Event</label>
                  <input
                    type="text"
                    readOnly
                    value={assessment.event}
                    className="mt-1 block w-full rounded-md border-gray-300 shadow-sm bg-gray-50"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700">Hazard</label>
                  <input
                    type="text"
                    readOnly
                    value={assessment.hazard}
                    className="mt-1 block w-full rounded-md border-gray-300 shadow-sm bg-gray-50"
                  />
                </div>
              </div>

              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700">Consequence</label>
                <input
                  type="text"
                  readOnly
                  value={assessment.consequence}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm bg-gray-50"
                />
              </div>

              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700">Current Controls</label>
                <input
                  type="text"
                  readOnly
                  value={assessment.current_controls}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm bg-gray-50"
                />
              </div>

              {matrixType === 'ICAO' ? (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Probability</label>
                    <input
                      type="number"
                      {...register(`assessments.${index}.probability`)}
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Severity</label>
                    <input
                      type="text"
                      {...register(`assessments.${index}.severity`)}
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm"
                    />
                  </div>
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Likelihood</label>
                    <input
                      type="number"
                      {...register(`assessments.${index}.likelihood`)}
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700">Impact</label>
                    <input
                      type="number"
                      {...register(`assessments.${index}.impact`)}
                      className="mt-1 block w-full rounded-md border-gray-300 shadow-sm"
                    />
                  </div>
                </div>
              )}

              <div className="mt-4">
                <label className="block text-sm font-medium text-gray-700">Tolerability</label>
                <input
                  type="text"
                  {...register(`assessments.${index}.tolerability`)}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm"
                />
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 flex justify-end">
          <button
            type="submit"
            disabled={isSubmitting}
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700 disabled:opacity-50"
          >
            {isSubmitting ? 'Saving...' : 'Save Assessments'}
          </button>
        </div>
      </form>
    </div>
  );
}
